comms.text:
@1 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@2 קַבֵּל יָת חֻשְׁבַּן בְּנֵי גֵרְשׁוֹן אַף אִנוּן לְבֵית אֲבָהַתְהוֹן לְזַרְעֲיַתְהוֹן:
@3 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא עַד בַּר חַמְשִׁין שְׁנִין תִּמְנֵי יַתְהוֹן כָּל דְאָתֵי לְחַיָלָא חֵילָא לְמִפְלַח פּוּלְחָנָא בְּמַשְׁכַּן זִמְנָא:
@4 דֵין פּוּלְחַן זַרְעֲיַת גֵרְשׁוֹן לְמִפְלַח וּלְמַטוּל:
@5 וְיִטְלוּן יָת יְרִיעַת מַשְׁכְּנָא וְיָת מַשְׁכַּן זִמְנָא חוֹפָאֵהּ וְחוֹפָאָה דְסַסְגוֹנָא דִי עֲלוֹהִי מִלְעֵלָא וְיָת פְּרָסָא דִתְרַע מַשְׁכַּן זִמְנָא:
@6 וְיָת סְרָדֵי דְדַרְתָּא וְיָת פְּרָסָא דְמַעֲלָנָא דִתְרַע דַרְתָּא דִי עַל מַשְׁכְּנָא וְעַל מַדְבְּחָא סְחוֹר סְחוֹר וְיָת אַטוּנֵיהוֹן וְיָת כָּל מָנֵי פּוּלְּחַנְהוֹן וְיַת כָּל דִי יִתְמְסַר לְהוֹן וְיִפְלְחוּן:
@7 עַל מֵימַר אַהֲרֹן וּבְנוֹהִי יְהֵי כָּל פּוּלְחַן בְּנֵי גֵרְשׁוֹן לְכָל מַטוּלְהוֹן וּלְכֹל פּוּלְחַנְהוֹן וּתְמַנוּן עֲלֵיהוֹן בְּמַטָרָא יָת כָּל מַטוּלְהוֹן:
@8 דֵין פּוּלְחַן זַרְעֲיַת בְּנֵי גֵרְשּׁוֹן בְּמַשְׁכַּן זִמְנָא וּמַטַרְתְּהוֹן בִּידָא דְאִיתָמָר בַּר אַהֲרֹן כַּהֲנָא:
@9 בְּנֵי מְרָרִי לְזַרְעֲיַתְהוֹן לְבֵית אֲבָּהַתְהוֹן תִּמְנֵי יַתְהוֹן:
@10 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין תִּמְנִנוּן כָּל דְאָתֵי לְחֵילָא לְמִפְלָח יָת פּוּלְחַן מַשְׁכַּן זִמְנָא:
@11 וְדָא מַטְרַת מַטוּלְהוֹן לְכָל פּוּלְחַנְהוֹן בְּמַשְׁכַּן זִמְנָא דַפֵּי מַשְׁכְּנָא וְעַבְרוֹהִי וְעַמוּדוֹהִי וְסַמְכוֹהִי:
@12 וְעֲמוּדֵי דְדַרְתָּא סְחוֹר סְחוֹר וְסַמְכֵיהוֹן וְסִכֵּיהוֹן וְאַטוּנֵיהוֹן לְכָל מָנֵיהוֹן וּלְכֹל פּוּלְחַנְהוֹן וּבִשְׁמָהָן תְּמַנוּן יָת מָנֵי מַטְרַת מַטוּלְהוֹן:
@13 דֵין פּוּלְחַן זַרְעֲיַת בְּנֵי מְרָרִי לְכָל פּוּלְחַנְהוֹן בְּמַשְׁכַּן זִמְנָא בִּידָא דְאִיתָמָר בַּר אַהֲרֹן כַּהֲנָא:
@14 וּמְנָא משֶׁה וְאַהֲרֹן וְרַבְרְבֵי כְנִשְׁתָּא יָת בְּנֵי קְהָת לְזַרְעֲיַתְהוֹן וּלְבֵית אֲבָהַתְהוֹן:
@15 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין כָּל דְאָתֵי לְחֵילָא לְפוּלְחָנָא בְּמַשְׁכַּן זִמְנָא:
@16 וַהֲווֹ מִנְיָנֵיהוֹן לְזַרְעֲיַתְהוֹן תְּרֵין אַלְפִין שְׁבַע מְאָה וְחַמְשִׁין:
@17 אִלֵין מִנְיָנֵי זַרְעֲיַת קְהָת כָּל דְפָלַח בְּמַשְׁכַּן זִמְנָּא דִי מְנָא משֶׁה וְאַהֲרֹן עַל מֵימְרָא דַיְיָ בִּידָא דְמשֶׁה:
@18 וּמִנְיָנֵי בְּנֵי גֵרְשׁוֹן לְזַרְעֲיַתְהוֹן וּלְבֵית אֲבָהַתְהוֹן:
@19 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין כָּל דְאָתֵי לְחֵילָא לְפוּלְחָנָא בְּמַשְׁכַּן זִמְנָא:
@20 וַהֲווֹ מִנְיָנֵהוֹן לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן תְּרֵין אַלְפִין וְשִׁית מְאָה וּתְלָתִין:
@21 אִלֵין מִנְיָנֵי זַרְעֲיַת בְּנֵי גֵרְשׁוֹן כָּל דְפָלַח בְּמַשְׁכַּן זִמְנָא דִי מְנָא משֶׁה וְאַהֲרֹן עַל מֵימְרָא דַיְיָ:
@22 וּמִנְיָנֵי זַרְעֲיַת בְּנֵי מְרָרִי לְזַרְעֲיַתְהוֹן לְבֵית אֲבָהַתְהוֹן:
@23 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין כָּל דְאָתֵי לְחֵילָא לְפוּלְחָנָא בְּמַשְׁכַּן זִמְנָא:
@24 וַהֲווֹ מִנְיָנֵיהוֹן לְזַרְעֲיַתְהוֹן תְּלָתָא אַלְפִין וּמָאתָן:
@25 אִלֵין מִנְיָנֵי זַרְעֲיַת בְּנֵי מְרָרִי דִי מְנָא משֶׁה וְאַהֲרֹן עַל מֵימְרָא דַיְיָ בִּידָא דְמשֶׁה:
@26 כָּל מִנְיָנַיָא דִי מְנָא משֶׁה וְאַהֲרֹן וְרַבְרְבֵי יִשְׂרָאֵל יָת לֵוָאֵי לְזַרְעֲיַתְהוֹן וּלְבֵית אֲבָהַתְהוֹן:
@27 מִבַּר תְּלָתִין שְׁנִין וּלְעֵלָא וְעַד בַּר חַמְשִׁין שְׁנִין כָּל דְאָתֵי לְמִפְלַח פּוּלְחַן פּוּלְחָנָא וּפוּלְחַן מַטוּל בְּמַשְׁכַּן זִמְנָא:
@28 וַהֲווֹ מִנְיָנֵיהוֹן תְּמַנְיָא אַלְפִין וַחֲמֵשׁ מְאָה וְתַמְנָן:
@29 עַל מֵימְרָא דַיְיָ מְנָא יָתְהוֹן בִּידָא דְמשֶׁה גְבַר גְבַר עַל פּוּלְחָנֵהּ וְעַל מַטוּלֵהּ וּמִנְיָנוֹהִי דִי פַקִיד יְיָ יָת משֶׁה:
@30 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@31 פַּקֵיד יָת בְּנֵי יִשְׂרָאֵל וִישַׁלְחוּן מִן מַשְׁרִיתָא כָּל דִסְגִיר וְכָל דְדָאֵב וְכֹל דִמְסָאָב לִטְמֵי נַפְשָׁא דֶאֱנָשָׁא:
@32 מִדְכַר עַד נוּקְבָא תְּשַׁלְחוּן לְמִבָּרָא לְמַשְׁרִיתָא תְּשַׁלְחֻנוּן וְלָא יְסַאֲבוּן יָת מַשְׁרִיתְהוֹן דִי שְׁכִינְתִּי שַׁרְיָא בֵינֵיהוֹן:
@33 וַעֲבָדוּ כֵן בְּנֵי יִשְׂרָאֵל וְשַׁלְחוּ יָתְהוֹן לְמִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי מַלִיל יְיָ עִם משֶׁה כֵּן עֲבָדוּ בְּנֵי יִשְׂרָאֵל:
@34 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@35 מַלֵל עִם בְּנֵי יִשְׂרָאֵל גְבַר אוֹ אִתְּתָא אֲרֵי יַעְבְּדוּן מִכָּל חוֹבֵי אֱנָשָׁא לְשַׁקָרָא שְׁקָר קֳדָם יְיָ וְיֵחוֹב אֱנָשָׁא הַהוּא:
@36 וִיוַדוּן יָת חוֹבֵיהוֹן דִי עֲבָדוּ וְיָתֵב יָת חוֹבְתֵהּ בְּרֵישֵׁהּ וְחֻמְשֵׁהּ יוֹסֵף עֲלוֹהִי וְיִתֵּן לִדְחָב לֵהּ:
@37 וְאִם לֵית לִגְבַר פָּרִיק לַאֲתָבָא חוֹבְתָא לֵהּ חוֹבְתָא דִמְתֵב קֳדָם יְיָ לְכַהֲנָא בַּר מִדְכַר כִּפּוּרַיָא דִי יְכַפֵּר בֵּהּ עֲלוֹהִי:
@38 וְכָל אַפְרָשׁוּתָא לְכָל קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל דִי יְקָרְבוּן לְכַהֲנָא דִלֵהּ יְהֵא:
@39 וּגְבַר יָת מַעֲשַׂר קוּדְשֵׁהּ דִלֵהּ יְהוֹן גְבַר דְיִתֵּן לְכַהֲנָא דִלֵהּ יְהֵא:
@40 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@41 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר גְבַר אֲרֵי תִסְטֵי אִתְּתֵהּ וּתְשַׁקֵר בֵּהּ שְׁקָר:
@42 וְיִשְׁכֻּב גְבַר יָתַהּ שָׁכְבַת זַרְעָא וִיהֵי מְכַסָא מֵעֵינֵי בַעְלַהּ וּמִטַמְרָא וְהִיא מְסָאֲבָא וְסָהִיד לֵית בַּהּ וְהִיא לָא אִתַּחָדַת:
@43 וְיֶעְבַּר עֲלוֹהִי רוּחַ קִנְאָה וִיקַנֵי יָת אִתְּתֵהּ וְהִיא מְסָאֲבָא אוֹ עֲבַר עֲלוֹהִי רוּחַ קִנְאָה וִיקַנֵי יָת אִתְּתֵהּ וְהִיא לָא מְסָאֲבָא:
@44 וְיַיְתֵי גַבְרָא יָת אִתְּתֵהּ לְוַת כַּהֲנָא וְיַיְתֵי יָת קֻרְבָּנַהּ עֲלַהּ חַד מִן עַסְרָא בִּתְלַת סְאִין קִמְחָא שְׂעָרִין לָא יְרִיק עֲלוֹהִי מִשְׁחָא וְלָא יִתֵּן עֲלוֹהִי לְבֻנְתָּא אֲרֵי מִנְחַת קִנְאָתָא הוּא מִנְחַת דוּכְרָנָא מַדְכָּרַת חוֹבָא:
@45 וִיקָרֵב יָתַהּ כַּהֲנָא וִיקִימִנַהּ קֳדָם יְיָ:
@46 וְיִסַב כַּהֲנָא מֵי כִיוֹר בְּמַן דַחֲסָף וּמִן עַפְרָא דִי יְהֵי בִּיסוֹדֵי מַשְׁכְּנָא יִסַב כַּהֲנָא וְיִתֵּן לְמַיָא:
@47 וִיקֵים כַּהֲנָא יָת אִתְּתָא קֳדָם יְיָ וְיִפְרַע יָת רֵישָׁא דְאִתְּתָא וְיתֵּן עַל יְדָהָא יָת מִנְחַת דוּכְרָנָא מִנְחַת קִנְאָתָא הִיא וּבִידָא דְכַהֲנָא יְהוֹן מַיָא מְרִירַיָא מְלַטְטַיָא:
@48 וְיוֹמֵי יָתַהּ כַּהֲנָא וְיֵימַר לְאִתְּתָא אִם לָא שְׁכִיב גְבַר יָתִיךְ וְאִם לָא סְטִּית לְאִסְתְּאָבָא בַּר מִבַּעֲלִיךְ הֱוֵי זַכָּאָה מִמַיָא מְרִירַיָא מְלַטְטַיָא הָאִלֵין:
@49 וְאַתְּ אֲרֵי סְטִית בַּר מִבַּעֲלִיךְ וַאֲרֵי אִסְתָּאָבְתְּ וִיהַב גְבַר בִּיךְ יָת שְׁכֻבְתֵּהּ בַּר מִבַּעֲלִיךְ:
@50 וְיוֹמֵי כַהֲנָא יָת אִתְּתָא בְּמוֹמָתָא דִלְוָטָּא וְיֵימַר כַּהֲנָא לְאִתְּתָא יִתֵּן יְיָ יָתִיךְ לִלְוַטּ וּלְמוֹמֵי בְּגוֹ עַמִיךְ בִּדְיִתֵּן יְיָ יָת יַרְכִּיךְ מַסְיָא וְיָת מְעַיְכִי נְפִיחִין:
@51 וְיֵעֲלוּן מַיָא מְלַטְטַיָא הָאִלֵין בִּמְעַיְכִי לַאֲפָחָא מְעִין וּלְאַמְסָאָה יַרְכָּא וְתֵימַר אִתְּתָא אָמֵן אָמֵן:
@52 וְיִכְתּוֹב יָת לְוָטַיָא הָאִלֵין כַּהֲנָא בְּסִפְרָא וְיִמְחוֹק לְמַיָא מְרִירַיָא:
@53 וְיַשְׁקֵי יָת אִתְּתָא יָת מַיָא מְרִירַיָא מְלַטְטַיָא וְיֵעֲלוּן בַּהּ מַיָא מְלַטְטַיָא לִמְרִירוּ:
@54 וְיִסַב כַּהֲנָא מִידָא דְאִתְּתָא יָת מִנְחַת קִנְאָתָא וִירֵים יָת מִנְחָתָא קָדָם יְיָ וִיקָרֵב יָתַהּ לְמַדְבְּחָא:
@55 וְיִקְמוֹץ כַּהֲנָא מִן מִנְחָתָא יָת אַדְכַּרְתָּהּ וְיַסֵק לְמַדְבְּחָא וּבָתַר כֵּן יַשְׁקֵי יָת אִתְּתָא יָת מַיָא:
@56 וְיַשְׁקִנָהּ יָת מַיָא וּתְהֵי אִם אִסְתָּאָבַת וְשַׁקָרַת שְׁקָר בְּבַעֲלַהּ וְיֵעֲלוּן בַּה מַיָא מְלַטְטַיָא לִמְרִירוּ וְיִפְּחוּן מְעָהָא וְתִתְמְסֵי יַרְכַהּ וּתְהֵי אִתְּתָא לִלְוַט בְּגוֹ עַמָהּ:
@57 וְאִם לָא אִסתָּאָבַת:אִתְּתָא וְדַכְוָאָה הִיא וְתִפּוֹק זַכָּאָה וְתַעְדִי עִדוּי:
@58 דָא אוֹרַיְתָא דְקִנְאָתָא דִי תִסְטֵי אִתְּתָא בַּר מִבַּעֲלַהּ וְתִסְתָּאָב:
@59 אוֹ גְבַר דִי תֶעְבַּר עֲלוֹהִי רוּחַ קִנְאָה וִיקַנֵי יָת אִתְּתֵהּ וִיקֵם יָת אִתְּתָא קֳדָם יְיָ וְיַעֲבֵד לַהּ כַּהֲנָא יָת כָּל אוֹרַיְתָא הָדָא:
@60 וִיהֵי זַכָּאָה גַבְרָא מֵחוֹבָא וְאִתְּתָא הַהִיא תְּקַבֵּל יָת חוֹבָהּ:
@61 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@62 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר אוֹ אִתְּתָא אֲרֵי יְפָרֵשׁ לְמִדַר נְדַר נְזִירוּ לְמֵיזַר קֳדָם יְיָ:
@63 מֵחֲמַר חֲדַת וְעַתִּיק יַנְזִיר חַל דַחֲמַר חֲדַת וְחַל דַחֲמַר עַתִּיק לָא יִשְׁתֵּי וְכָל מַתְרוּת עִנְבִין לָא יִשְׁתֵּי וְעִנְבִין רַטִיבִין וִיבֵשִׁין לָא יֵיכוּל:
@64 כֹּל יוֹמֵי נִזְרֵהּ מִכֹּל דְיִתְעֲבֵד מִגֻפְנָא דְחַמְרָא מִפּוּרְצְנִין וְעַד עִצוּרִין לָא יֵיכוּל:
@65 כָּל יוֹמֵי נְדַר נִזְרֵהּ מַסְפַּר לָא יֶעְבַּר עַל רֵישֵׁהּ עַד מִשְׁלַם יוֹמַיָא דְיַנְזֵר קֳדָם יְיָ קַדִישׁ יְהֵי מַרְבֵּי פֵרוּעַ שְׂעַר רֵישֵׁהּ:
@66 כָּל יוֹמִין דְיַנְזֵר קֳדָם יְיָ עַל נַפְשָׁא דְמֵתָא לָא יֵיעוּלּ:
@67 לְאָבוּהִי וּלְאִמֵהּ לְאַחוֹהִי וּלְאַחָתֵהּ לָא יִסְתָּאַב לְהוֹן בְּמוֹתְהּוֹן אֲרֵי כְּלִילָא דֶאֱלָהֵהּ עַל רֵישֵׁהּ:
@68 כֹּל יוֹמֵי נִזְרֵהּ קַדִישׁ הוּא קֳדָם יְיָ:
@69 וַאֲרֵי יְמוּת מֵתָא עֲלוֹהִי בִּתְכֵּף שָׁלוּ וִיסָאֵב רֵישׁ נִזְרֵהּ וִיגַלַח רֵישֵׁהּ בְּיוֹמָא דִדְכוּתֵהּ בְּיוֹמָא שְׁבִיעָאָה יְגַלְחִנֵהּ:
@70 וּבְיוֹמָא תְמִינָאָה יַיְתֵי תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא:
@71 וְיַעְבֵּד כַּהֲנָא חַד לְחַטָאתָא וְחַד לַעֲלָתָא וִיכַפֵּר עֲלוֹהִי מִדְחָב עַל מִתָא וִיקַדַשׁ יָת רֵישֵׁהּ בְּיוֹמָא הַּהוּא:
@72 וְיַזֵר קֳדָם יְיָ יָת יוֹמֵי נִזְרֵהּ וְיַיְתִי אִמַר בַּר שַׁתֵּהּ לַאֲשָׁמָא וְיוֹמַיָא קַדְמָאֵי יִבְטְלוּן אֲרֵי אִסְתָּאַב נִזְרֵהּ:
@73 וְדָא אוֹרַיְתָא דִנְזִירָא בְּיוֹם מִשְׁלַם יוֹמֵי נִזְרֵהּ יַיְתִי יָתֵהּ לִתְרַע מַשְׁכַּן זִמְנָא:
@74 וִיקָרֵב יָת קֻרְבָּנֵהּ קֳדָם יְיָ אִמַר בַּר שַׁתֵּהּ שְׁלִים חַד לַעֲלָתָא וְאִמַרְתָּא חֲדָא בַּת שַׁתָּהּ שְׁלֶמְתָּא לְחַטָאתָא וּדְכַר חַד שְׁלִים לְנִכְסַת קוּדְשַׁיָא:
@75 וְסַלָא דְפַּטִרִיָא סֻלְּתָּא גְרִיצַן דְפִילָן בִּמְשַׁח וְאִסְפּוֹגִין פַּטִירִין דִמְשִׁיחִין בִּמְשָׁח וּמִנְחַתְהוֹן וְנִסְכֵּיהוֹן:
@76 וִיקָרֵב כַּהֲנָא קֳדָם יְיָ וְיַעְבֵּד יָת חַטָאתֵהּ וְיָת עֲלָתֵהּ:
@77 וְיָת דִכְרָא יַעְבֵּד נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ עַל סַלָא דְפַטִּירַיָא וְיַעְבֵּד כַּהֲנָא יָת מִנְחָתֵהּ וְיָת נִסְכֵּהּ:
@78 וִיגַלַח נְזִירָא בִּתְרַע מַשְׁכַּן זִמְנָא יָת רֵישׁ נִזְרֵהּ וְיִסַב יָת שְׂעַר רֵישׁ נִזְרֵהּ וְיִתֵּן עַל אֶשָׁתָא דִי תְחוֹת דוּדָא דְנִכְסַת קוּדְשַׁיָא:
@79 וְיִסַב כַּהֲנָא יָת דְרָעָא בְּשֵׁלָא מִן דִכְרָא וּגְרִצְתָּא פַטִּירְתָּא חֲדָא מִן סַלָא וְאִסְפּוֹג פַּטִיר חָד וְיִתֵּן עַל יְדֵי נְזִירָא בָּתַר דְגַלַח יָת נִזְרֵהּ:
@80 וִירִים יָתְהוֹן כַּהֲנָא אֲרָמָא קֳדָם יְיָ קוּדְשָׁא הוּא לְכַהֲנָא עַל חַדְיָא דַאֲרָמוּתָא וְעַל שַׁקָא דְאַפְרָשׁוּתָא וּבָתַר כֵּן יִשְׁתֵּי נְזִירָא חַמְרָא:
@81 דָא אוֹרַיְתָא דִנְזִירָא דִי יִדַר קֻרְבָּנֵהּ קֳדָם יְיָ עַל נִזְרֵהּ בַּר מִדְתַדְבֵּק יְדֵהּ כְּפוּם נִדְרֵהּ דִי יִדַר כֵּן יַעְבֵּד עַל אוֹרַיְתָא דְנִזְרֵהּ:
@82 וּמַלִיל יְיָ עִם משֶׁה לְמֵימָר:
@83 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי לְמֵימַר כְּדֵין תְּבָרְכוּן יָת בְּנֵי יִשְׂרָאֵל תֵּימְרוּן לְהוֹן:
@84 יְבָרְכִינָךְ יְיָ וְיִטְרִינָךְ:
@85 יַנְהַר יְיָ שְׁכִנְתֵּהּ לְוָתָךְ וִירַחֵם יָתָךְ:
@86 יִסַב יְיָ אַפֵּהּ לְוָתָךְ וִישַׁוֵי לָךְ שְׁלָם:
@87 וִישַׁווּן יָת בִּרְכַּת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנָא אֲבָרֵכִנוּן:
@88 וַהֲוָה בְּיוֹמָא דְשֵׁיצֵי משֶׁה לַאֲקָמָא יָת מַשְׁכְּנָא וְרַבִּי יָתֵהּ וְקַדִישׁ יָתֵהּ וְיָת כָּל מָנוֹהִי וְיָת מַדְבְּחָא וְיָת כָּל מָנוֹהִי וְרַבִּנוּן וְקַדֵישׁ יָתְהוֹן:
@89 וּקְרִיבוּ רַבְרְבֵי יִשְׂרָאֵל רֵישֵׁי בֵּית אֲבָהַתְהוֹן אִנוּן רַבְרְבֵי שִׁבְטַיָא אִנוּן דְקַיְמִין עַל מִנְיָנַיָא:
@90 וְאַיְתִיוּ יָת קֻרְבָּנֵיהוֹן קֳדָם יְיָ שִׁית עֶגְלָן כַּד מְחַפְיָן וּתְרֵי עֲשַׂר תּוֹרִין עֶגְלְתָא עַל תְּרֵין רַבְרְבַיָא וְתוֹר לְחַד וְקָרִיבוּ יָתְהוֹן לָקֳדָם מַשְׁכְּנָא:
@91 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@92 קַבֵּל מִנְהוֹן וִיהוֹן לְמִפְלַח יָת פּוּלְחַן מַשְׁכַּן זִמְנָא וְתִתֵּן יָתְהוֹן לְלֵוָאֵי גְבַר כְּמִסַת פּוּלְחָנֵהּ:
@93 וּנְסֵיב משֶׁה יָת עֶגְלָתָא וְיָת תּוֹרִין וִיהַב יָתְהוֹן לְלֵוָאֵי:
@94 יָת תַּרְתֵּין עֶגְלָתָא וְיָת אַרְבַּעַת תוֹרֵי יְהַב לִבְנֵי גֵרְשׁוֹן כְּמִסַת פּוּלְחַנְהוֹן:
@95 וְיָת אַרְבַּע עֶגְלָתָא וְיָת תְּמַנְיָא תוֹרֵי יְהַב לִבְנֵי מְרָרִי כְּמִסַת פּוּלְחַנְהוֹן בִּידָא דְאִיתָמָר בַּר אַהֲרֹן כַּהֲנָא:
@96 וְלִבְנֵי קְהָת לָא יְהָב אֲרֵי פוּלְחַן קוּדְשָׁא עֲלֵיהוֹן בְּכַתְפָּא נָטְלִין:
@97 וְקָרִיבוּ רַבְרְבַיָא יָת חֲנֻכַּת מַדְבְּחָא בְּיוֹמָא דְרַבִּיוּ יָתֵהּ וְקָרִיבוּ רַבְרְבַיָא יָת קֻרְבַּנְהוֹן לְּקֳדָם מַדְבְּחָא:
@98 וַאֲמַר יְיָ לְמשֶׁה רַבָּא חַד לְיוֹמָא רַבָּא חַד לְיוֹמָא יְקָרְבוּן יָת קֻרְבַּנְהוֹן לַחֲנֻכַּת מַדְבְּחָא:
@99 וַהֲוָה דִמְקָרַב בְּיוֹמָא קַדְמָאָה יָת קֻרְבָּנֵהּ נַחְשׁוֹן בַּר עַמִינָדָב לְשִׁבְטָא דִיהוּדָה:
@100 וְקֻרְבָּנֵהּ מְגִסְתָּא דִכְסַף חֲדָא מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלַהּ מִזְרְקָא חַד דִכְסַף מַתְקְלֵהּ שַׁבְעִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא תַּרְוֵיהוֹן מְלַן סֻלְתָּא דְּפִילָא בִמְשַׁח לְמִנְחָתָא:
@101 בָּזִיכָא חֲדָא מַתְקַל עֲשַׂר סִלְעִין הִיא דִדְהַב מַלְיָא קְטוֹרֶת בּוּסְמַיָא:
@102 תּוֹר חַד בַּר תּוֹרֵי דְּכַר חַד אִמַּר חַד בַּר שַׁתֵּהּ לַעֲלָתָא:
@103 צְפִיר בַּר עִזִּין חַד לְחַטָּאתָא:
@104 וּלְנִכְסַת קוּדְשַׁיָּא תּוֹרִין תְּרֵין דִּכְרִין חַמְשָׁא גְּדָיֵי חַמְשָׁא אִמְּרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵּין קֻרְבָּנָא דְנַחְשׁוֹן בַּר עַמִּינָדָב:
@105 בְּיוֹמָא תִּנְיָנָא קָרִיב נְתַנְאֵל בַּר צוּעָר רַבָּה דְיִשָׂשׂכָר:
@106 קָרִיב יָת קֻרְבָּנֵהּ מְגִסְתָּא דִכְסַף חֲדָא מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלֵהּ מִזְרְקָא חַד דִכְסַף מַתְקְלַהּ שַׁבְעִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא תַּרְוֵיהוֹן מְלַן סֻלְתָּא דְפִילָא בִמְשַׁח לְמִנְחָתָא:
@107 בָּזִיכָא חֲדָא מַתְקַל עֲשַׂר סִלְעִין הִיא דִדְהַב מַלְיָא קְטוֹרֶת בּוּסְמַיָא:
@108 תּוֹר חַד בַּר תּוֹרֵי דְכַר חַד אִמַר חַד בַּר שַׁתֵּהּ לַעֲלָתָא:
@109 צְפִיר בַּר עִזִין חַד לְחַטָאתָא:
@110 וּלְנִכְסַת קוּדְשַׁיָא תּוֹרִין תְּרֵין דִכְרִין חַמְשָׁא גְדָיֵי חַמְשָׁא אִמְרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵין קֻרְבַּן נְתַנְאֵל בַּר צוּעָר:
@111 בְּיוֹמָא תְּלִיתָאָה רַבָּא לִבְנֵי זְבוּלֻן אֱלִיאָב בַּר חֵלֹן:
@112 קֻרְבָּנֵהּ מְגִסְתָּא דִכְסַף חֲדָא מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלַהּ מִזְרְקָא חַד דִכְסַף מַתְקְלֵהּ שַׁבְעִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא תַּרְוֵיהוֹן מְלַן סֻלְתָּא דְפִילָא בִמְשַׁח לְמִנְחָתָא:
@113 בָּזִיכָא חֲדָא מַתְקַל עֲשַׂר סִלְעִין הִיא דִדְהַב מַלְיָא קְטוֹרֶת בּוּסְמַיָא:
@114 תּוֹר חַד בַּר תּוֹרֵי דְכַר חַד אִמַר חַד בַּר שַׁתֵּהּ לַעֲלָתָא:
@115 צְפִיר בַּר עִזִין חַד לְחַטָאתָא:
@116 וּלְנִכְסַת קוּדְשַׁיָא תּוֹרִין תְּרֵין דִכְרִין חַמְשָׁא גְדָיֵי חַמְשָׁא אִמְרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵין קֻרְבַּן אֱלִיאָב בַּר חֵלוֹן:
@117 בְּיוֹמָא רְבִיעָאָה רַבָּא לִבְנֵי רְאוּבֵן אֱלִיצוּר בַּר שְׁדֵיאוּר:
@118 קֻרְבָּנֵהּ מְגִסְתָּא דִכְסַף חֲדָא מְאָה וּתְלָתִין סִלְעִין הֲוָה מַתְקְלַהּ מִזְרְקָא חַד דִכְסַף מַתְקְלֵהּ שַׁבְעִין סִלְעִין בְּסִלְעֵי קוּדְשָׁא תַּרְוֵיהוֹן מְלַן סֻלְתָּא דְפִילָא בִמְשַׁח לְמִנְחָתָא:
@119 בָּזִיכָא חֲדָא מַתְקַל עֲשַׂר סִלְעִין הִיא דִדְהַב מַלְיָא קְטוֹרֶת בּוּסְמַיָא:
@120 תּוֹר חַד בַּר תּוֹרֵי דְכַר חַד אִמַר חַד בַּר שַׁתֵּהּ לַעֲלָתָא:
@121 צְפִיר בַּר עִזִין חַד לְחַטָאתָא:
@122 וּלְנִכְסַת קוּדְשַׁיָא תּוֹרִין תְּרֵין דִכְרִין חַמְשָׁא גְדָיֵי חַמְשָׁא אִמְרִין בְּנֵי שַׁתָּא חַמְשָׁא דֵין קֻרְבַּן אֱלִיצוּר בַּר שְׁדֵיאוּר:
